actions.script:
valid = false
def parse = { value ->
    def text = value == null ? '' : value.toString().trim()
    if (!text) return BigDecimal.ZERO
    if (!(text ==~ /-?\d*\.?\d+/)) throw new NumberFormatException()
    return new BigDecimal(text)
}
try {
    quantityValue = parse(quantity)
    unitAmountValue = parse(unitAmount)
    discountPercentValue = parse(discountPercent)
    taxPercentageValue = parse(taxPercentage)
} catch (NumberFormatException ignored) {
    ec.message.addError('Quantity, Unit Price, Discount and GST Rate must be numbers.')
    return
}
if (quantityValue.signum() <= 0) { ec.message.addError('Quantity must be greater than zero.'); return }
if (unitAmountValue.signum() < 0) { ec.message.addError('Unit price cannot be negative.'); return }
if (discountPercentValue < 0 || discountPercentValue > 100) {
    ec.message.addError('Discount must be between 0 and 100 percent.'); return
}
if (taxPercentageValue.signum() < 0) { ec.message.addError('GST rate cannot be negative.'); return }
// Zero price and a full discount remain valid for existing free-item workflows.
valid = true

def taxed = calculation.taxedItems.first()
def details = taxed.taxBreakdowns ?: []
lineFields = [taxableAmount:ec.l10n.roundCurrency(taxed.taxableAmount, header.currencyUomId),
        totalTaxAmount:taxed.totalTaxAmount, discountAmount:discountAmount,
        salesTaxDetailsJson:groovy.json.JsonOutput.toJson(details)]
for (String code in ['CGST','SGST','IGST']) {
    def components = details.findAll { it.taxName == code }
    lineFields[code.toLowerCase()+'Amount'] = components.sum { it.taxAmount } ?: 0
    lineFields[code.toLowerCase()+'Rate'] = components.sum { it.taxRate } ?: 0
}

boolean hasLines = false
for (part in parts) {
    def items = ec.entity.find('mantle.order.OrderItem').condition('orderId',orderId).condition('orderPartSeqId',part.orderPartSeqId).list()
    if (!items) continue // preserve imported opening balances without line detail
    hasLines = true
    // Older direct orders left their line tax unresolved until invoicing.
    if (documentType == 'SALES_ORDER') {
        for (row in items.findAll { it.taxableAmount == null && (it.productId || it.itemTypeEnumId == 'ItemProduct') }) {
            def discount = row.discountAmount != null ? row.discountAmount : ec.l10n.roundCurrency(
                    row.quantity * row.unitAmount * (row.discountPercent ?: 0) / 100, header.currencyUomId)
            def pricing = ec.service.sync().name('zenith.sales.SalesLineServices.get#CatalogOrderLineTax').parameters([
                    orderId:orderId,orderPartSeqId:part.orderPartSeqId,productId:row.productId,
                    productTaxCode:row.productTaxCode ?: row.hsnSacCode,quantity:row.quantity,unitAmount:row.unitAmount,
                    discountAmount:discount,isTaxInclusive:row.isTaxInclusive]).call()
            if (ec.message.hasError()) return
            row.setAll(pricing.lineFields); row.update()
        }
    }
    def partTotal = items.sum { row ->
        ec.service.sync().name('mantle.order.OrderServices.get#OrderItemTotal').parameters([orderItem:row]).call().itemTotal
    }
    partTotal = ec.l10n.roundCurrency(partTotal,header.currencyUomId)
    if (partTotal == part.partTotal) continue
    // The native updater also changes a single payment promise. Avoid changing a settled or split payment plan.
    def payments = ec.entity.find('mantle.account.payment.Payment').condition('orderId',orderId)
            .condition('orderPartSeqId',part.orderPartSeqId).list()
    if (payments.size() > 1 || payments.any { !(it.statusId in ['PmntProposed','PmntPromised','PmntDeclined']) }) {
        ec.message.addError('This order has existing payments. Review its payment plan before reconciling the order.'); return
    }
    ec.service.sync().name('mantle.order.OrderServices.update#OrderPartTotal').parameters([orderId:orderId,orderPartSeqId:part.orderPartSeqId]).call()
}
if (hasLines) ec.service.sync().name('mantle.order.OrderServices.update#OrderHeaderTotal').parameters([orderId:orderId]).call()

def items = ec.entity.find('mantle.account.invoice.InvoiceItem').condition('invoiceId',invoiceId).list()
def detailsByLine = ec.entity.find('zenith.erp.tax.TaxLineDetail')
        .condition('referenceType','InvoiceItem').condition('referenceId',invoiceId)
        .orderBy('sequenceNum').list().groupBy { it.referenceSeqId }
def taxable = BigDecimal.ZERO, cgst = BigDecimal.ZERO, sgst = BigDecimal.ZERO, igst = BigDecimal.ZERO, tax = BigDecimal.ZERO
for (item in items) {
    // A full discount stores a real zero; it must never fall back to the gross line value.
    taxable += (item.taxableAmount != null ? item.taxableAmount : ((item.quantity != null ? item.quantity : 1)*(item.amount ?: 0))) as BigDecimal
    cgst += (item.cgstAmount ?: 0) as BigDecimal
    sgst += (item.sgstAmount ?: 0) as BigDecimal
    igst += (item.igstAmount ?: 0) as BigDecimal
    if (item.cgstAmount != null || item.sgstAmount != null || item.igstAmount != null) {
        def prior = detailsByLine[item.invoiceItemSeqId] ?: []
        def gstNames = ['CGST','SGST','IGST']
        def breakdowns = prior.findAll { !(it.taxName in gstNames) }.collect { it.getMap() }
        boolean changed = false
        for (name in gstNames) {
            def key = name.toLowerCase()
            def rate = item.get(key+'Rate') ?: 0
            def amount = item.get(key+'Amount') ?: 0
            def previous = prior.findAll { it.taxName == name }
            boolean current = rate > 0 && previous &&
                    previous.sum { it.taxRate ?: 0 } == rate &&
                    previous.sum { it.taxAmount ?: 0 } == amount &&
                    previous.every { it.taxableAmount == item.taxableAmount &&
                            (it.isIncludedInPrice ?: 'N') == (item.isTaxInclusive ?: 'N') }
            if (current) {
                breakdowns.addAll(previous.collect { it.getMap() })
            } else if (rate > 0) {
                // Preserve the tax engine's authority/category on an amount-only edit.
                def row = previous.size() == 1 && previous[0].taxRate == rate ? previous[0].getMap() : [:]
                breakdowns.add(row + [taxName:name,taxRate:rate,taxableAmount:item.taxableAmount,
                        taxAmount:amount,countryGeoId:row.countryGeoId ?: 'IND',isIncludedInPrice:item.isTaxInclusive ?: 'N'])
                changed = true
            } else if (previous) {
                changed = true
            }
        }
        if (changed && breakdowns) {
            ec.service.sync().name('zenith.tax.TaxServices.store#TaxLineDetails').parameters([referenceType:'InvoiceItem',referenceId:invoiceId,referenceSeqId:item.invoiceItemSeqId,currencyUomId:invoice.currencyUomId,taxBreakdowns:breakdowns]).call()
        } else if (changed) {
            prior.each { it.delete() }
        }
    }
    tax += (item.totalTaxAmount != null ? item.totalTaxAmount : ((item.cgstAmount ?: 0)+(item.sgstAmount ?: 0)+(item.igstAmount ?: 0))) as BigDecimal
}
def grand=taxable+tax
def roundOff = BigDecimal.ZERO
if (invoice.currencyUomId == 'INR') {
    def orderLinked = invoice.invoiceTypeEnumId == 'InvoiceSales' &&
            ec.entity.find('mantle.order.OrderItemBilling').condition('invoiceId', invoiceId).count() > 0
    if (!orderLinked) roundOff = grand.setScale(0, java.math.RoundingMode.HALF_UP) - grand
}
def words=invoice.currencyUomId == 'INR' ? ec.service.sync().name('zenith.base.LocalizationServices.convert#AmountToWords').parameters([amount:grand+roundOff,currencyUomId:invoice.currencyUomId,organizationPartyId:invoice.fromPartyId]).call()?.amountInWords : invoice.amountInWords
ec.service.sync().name('update#mantle.account.invoice.Invoice').parameters([
    invoiceId:invoiceId, invoiceTotal:grand, unpaidTotal:grand + roundOff - (invoice.appliedPaymentsTotal ?: 0),
    totalTaxableAmount:taxable, totalCgst:cgst, totalSgst:sgst, totalIgst:igst,
    totalTaxAmount:tax, roundOffAmount:roundOff, amountInWords:words]).call()

// System-wide convention: invoiceTotal already includes tax; round-off is separate.
payableAmount=((invoice.invoiceTotal ?: 0)+(invoice.roundOffAmount ?: 0)-
    (invoice.appliedPaymentsTotal ?: 0)).setScale(2,java.math.RoundingMode.HALF_UP)

def seller=invoice.fromPartyId ? ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameters([partyId:invoice.fromPartyId]).call() : null
def buyer=invoice.toPartyId ? ec.service.sync().name('zenith.tax.TaxServices.get#PartyTaxRegistration').parameters([partyId:invoice.toPartyId]).call() : null
def prefix={ value -> def text=value?.toString()?.trim(); text && text.length()>=2 && text.substring(0,2)==~/[0-9]{2}/ ? text.substring(0,2) : null }
def state={ value -> def text=value?.toString()?.trim(); text && text==~/[0-9]{2}/ ? text : null }
def sellerState=prefix(invoice.supplierGstin) ?: state(invoice.supplierStateCode) ?: state(seller?.regionGeoId) ?: prefix(seller?.registrationNumber)
def buyerState=prefix(invoice.buyerGstin) ?: state(invoice.placeOfSupplyStateCode) ?: state(buyer?.regionGeoId) ?: prefix(buyer?.registrationNumber)
boolean interstate=(sellerState && buyerState && sellerState != buyerState) || invoice.isExport=='Y' || invoice.isSezSupply=='Y'
boolean zero=invoice.isReverseCharge=='Y' || ((invoice.isExport=='Y' || invoice.isSezSupply=='Y') && invoice.isWithPayment!='Y')
for (item in ec.entity.find('mantle.account.invoice.InvoiceItem').condition('invoiceId',invoiceId).list()) {
    def taxable=(item.taxableAmount != null ? item.taxableAmount : ((item.quantity != null ? item.quantity : 1)*(item.amount ?: 0))) as BigDecimal
    def rate=((item.cgstRate ?: 0)+(item.sgstRate ?: 0)+(item.igstRate ?: 0)) as BigDecimal
    def cr=interstate ? BigDecimal.ZERO : rate.divide(new BigDecimal(2),5,java.math.RoundingMode.HALF_UP)
    def sr=cr, ir=interstate ? rate : BigDecimal.ZERO
    def ca=zero ? BigDecimal.ZERO : (taxable*cr/100).setScale(2,java.math.RoundingMode.HALF_UP)
    def sa=zero ? BigDecimal.ZERO : (taxable*sr/100).setScale(2,java.math.RoundingMode.HALF_UP)
    def ia=zero ? BigDecimal.ZERO : (taxable*ir/100).setScale(2,java.math.RoundingMode.HALF_UP)
    def priorGst=(item.cgstAmount ?: 0)+(item.sgstAmount ?: 0)+(item.igstAmount ?: 0)
    def otherTax=zero ? BigDecimal.ZERO : (item.totalTaxAmount != null ? item.totalTaxAmount-priorGst : BigDecimal.ZERO)
    def amounts = [cgstRate:cr,sgstRate:sr,igstRate:ir,cgstAmount:ca,sgstAmount:sa,igstAmount:ia,totalTaxAmount:ca+sa+ia+otherTax]
    if (amounts.any { field, value -> item.get(field) != value }) {
        ec.service.sync().name('update#mantle.account.invoice.InvoiceItem').parameters(
                amounts + [invoiceId:invoiceId,invoiceItemSeqId:item.invoiceItemSeqId]).call()
    }
}
